const squareIndices=new Uint16Array([2,1,0,3,2,0]);const vsPoint="\n    attribute vec2 a_position;\n\n    uniform mat4 model;\n    uniform mat4 proj;\n    uniform float zoom;\n\n    uniform vec2 mouse;\n    uniform vec2 viewportSize;\n\n    const float DEG2RAD = 3.141592653589793 / 180.0;\n    float radius = 1.0;\n\n    void main() {\n\n        float lon = a_position.x * DEG2RAD;\n        float lat = a_position.y * DEG2RAD;\n\n        //lat += lat / 30.0;\n\n        // convert spherical to Cartesian\n        float x = radius * cos(lat) * cos(lon);\n        float y = radius * sin(lat);\n        float z = radius * cos(lat) * sin(lon);\n\n        vec3 position = vec3(x, y, z);\n\n        vec3 normalLocal = normalize(position);\n        vec3 normalWorld = normalize((model * vec4(normalLocal, 0.0)).xyz);\n\n        vec3 worldPos = (model * vec4(position, 1.0)).xyz;\n\n        if (worldPos.z > -990.1) {\n\n            vec4 clip = proj * model * vec4(position, 1.0);\n            vec3 ndc = clip.xyz / clip.w;\n\n            vec2 pointPx;\n            pointPx.x = ndc.x * viewportSize.x;\n            pointPx.y = ndc.y * viewportSize.y;\n\n            float pxDist = distance(pointPx,mouse);\n\n            // choose sizes\n            float base = 8.0;\n            float highlight = 40.0;\n            float radiusPx = 40.0;  // area where it grows\n\n            float size = base;\n            if (pxDist < radiusPx) {\n                float t = 1.0 - pxDist / radiusPx;\n                size = mix(base, highlight, t);\n            }\n\n            gl_Position = clip;\n            gl_PointSize = size; // set pixel radius of the vertex\n            return;\n        }\n\n        gl_PointSize = 0.0;\n        gl_Position = vec4(2.0, 2.0, 2.0, 1.0);\n    }\n";const fsPoint="\n    precision mediump float;\n\n    void main() {\n        // Convert fragment coordinate to [-1,1] range\n        vec2 p = gl_PointCoord * 2.0 - 1.0;\n\n        // Kill fragments outside the circle radius\n        if (dot(p, p) > 1.0) {\n            discard;\n        }\n\n        gl_FragColor = vec4(1.0, 0.6, 0.0, 1.0); // orange point\n    }\n";const vsGeo2="\n    attribute vec2 a_position;\n\n    uniform mat4 model;\n    uniform mat4 proj;\n\n    void main() {\n        float radius = 1.0;\n        float lon = radians(a_position.x);\n        float lat = radians(a_position.y);\n\n        float x = cos(lat) * cos(lon);\n        float y = sin(lat);\n        float z = cos(lat) * sin(lon);\n\n        vec3 spherePos = vec3(x, y, z) * radius;\n\n        gl_Position = proj * model * vec4(spherePos, 1.0);\n    }\n";const vsGeo="\n    attribute vec2 a_position;\n\n    uniform mat4 model;\n    uniform mat4 proj;\n\n    void main() {\n        gl_Position = proj * model * vec4(a_position.x, a_position.y, 0.0, 1.0);\n    }\n";const fsGeo="\n    precision mediump float;\n\n    void main() {\n        gl_FragColor = vec4(1.0, 1.0, 1.0,1.0);\n    }\n";// Vertex shader
const vsSource="\n    attribute vec4 a_position;\n    \n    uniform mat4 model;\n    uniform mat4 proj;\n    \n    attribute vec2 a_texCoord;\n    varying vec2 v_texCoord;\n    void main() {\n        gl_Position = proj * model * a_position;\n        v_texCoord = a_texCoord;\n    }\n";// Fragment shader
const fsSource="\n    precision mediump float;\n    varying vec2 v_texCoord;\n    uniform float alpha;\n    uniform sampler2D u_texture;\n    void main() {\n        vec4 colour = texture2D(u_texture, v_texCoord);\n        if (colour.a == 1.0) {\n            colour.a = alpha;\n        }\n        gl_FragColor = colour;\n    }\n";const vsSphere="\n    attribute vec4 a_position;\n    \n    uniform mat4 model;\n    uniform mat4 proj;\n\n    varying vec4 fragCoord;\n\n    void main() {\n        fragCoord = a_position;\n        gl_Position = proj * model * a_position;\n    }\n";const vsPlanet="\n    attribute vec4 a_position;\n    \n    uniform mat4 model;\n    uniform mat4 proj;\n\n    attribute vec2 a_texCoord;\n    varying vec2 v_texCoord;\n\n    varying vec4 fragCoord;\n\n    void main() {\n        v_texCoord = a_texCoord;\n        fragCoord = a_position;\n        gl_Position = proj * model * a_position;\n    }\n";const fsSphere="\n    precision mediump float;\n\n    varying vec4 fragCoord;\n\n    void main() {\n        vec4 colour = vec4(1.0,1.0,1.0,1.0);\n        if (fragCoord.x * fragCoord.x + fragCoord.y * fragCoord.y > 1.0) {\n            colour.a = 0.0;\n        }\n        gl_FragColor = colour;\n    }\n";// Fragment shader
const fsImageColourSource="\n    precision mediump float;\n    varying vec2 v_texCoord;\n    uniform sampler2D u_texture;\n    uniform vec4 u_colour;\n    void main() {\n        float alpha = texture2D(u_texture, v_texCoord)[3];\n        \n        if (alpha < 0.5) {\n            gl_FragColor = vec4(0.0,0.0,0.0,0.0);\n            return;\n        }\n        \n        gl_FragColor = u_colour;\n    }\n";const vsBackgroundSource="\n    attribute vec4 a_position;\n    \n    uniform mat4 model;\n    uniform mat4 proj;\n    \n    void main() {\n        gl_Position = proj * model * a_position;\n    }\n";const fsSpace="\n    precision mediump float;\n    \n    uniform float time;\n    uniform vec2 resolution;\n    uniform float transparency;\n    \n    vec4 textureRND2D(vec2 uv){\n        uv = floor(fract(uv)*1e3);\n        float v = uv.x+uv.y*1e3;\n        return fract(1e5*sin(vec4(v*1e-2, (v+1.)*1e-2, (v+1e3)*1e-2, (v+1e3+1.)*1e-2)));\n    }\n    \n    float noise(vec2 p) {\n        vec2 f = fract(p*1e3);\n        vec4 r = textureRND2D(p);\n        f = f*f*(3.0-2.0*f);\n        return (mix(mix(r.x, r.y, f.x), mix(r.z, r.w, f.x), f.y));\n    }\n    \n    float cloud(vec2 p) {\n        float v = 0.0;\n        v += noise(p*1.)*.50000;\n        v += noise(p*2.)*.2;\n        v += noise(p*4.)*.12500;\n        v += noise(p*8.)*.06250;\n        v += noise(p*16.)*.03125;\n        return v*v*v;\n    }\n    \n    void main( void ) {\n        vec2 p = (floor(gl_FragCoord.xy / 10.0) * 10.0 * 6.0 - resolution.xy) / min(resolution.x, resolution.y) * 0.05 / 8.0;\n        //vec2 p = (gl_FragCoord.xy * 6.0 - resolution.xy) / min(resolution.x, resolution.y) * 0.05 / 8.0;\n        p.y += sin(p.x * 150.0 + time) / 100.0 * gl_FragCoord.y / resolution.y;\n        p.x += time / 1000.0;\n        \n        vec3 c = vec3(0.0, 0.0, 1.0);\n        c.rgb += vec3(0.0, 0.0, 1.0) * cloud(p*.3+time*.001)*.6;\n        c.gbr += vec3(0.784, 1.0, 0.) * cloud(p*.2+time*.001)*.8;\n        c.grb += vec3(0.784, 0.0, 1.0) * cloud(p*.1+time*.001)*1.;\n        gl_FragColor = vec4(c, transparency);\n    }\n\n";const fsGround="\nprecision mediump float;\n\nuniform float time;\nuniform vec2 resolution;\n\nfloat hash(float n) { return fract(sin(n) * 1e4); }\nfloat hash(vec2 p) { return fract(1e4 * sin(17.0 * p.x + p.y * 0.1) * (0.1 + abs(sin(p.y * 13.0 + p.x)))); }\n\nfloat noise(float x) {\n    float i = floor(x);\n    float f = fract(x);\n    float u = f * f * (3.0 - 2.0 * f);\n    return mix(hash(i), hash(i + 1.0), u);\n}\n\nfloat fbm(float x) {\n    float v = 0.0;\n    float a = 0.5;\n    float shift = float(100);\n    for (int i = 0; i < 1; ++i) {\n        v += a * noise(x);\n        x = x * 2.0 + shift;\n        a *= 0.5;\n    }\n    return v;\n}\n\nfloat noise2D(vec2 x) {\n    vec2 i = floor(x);\n    vec2 f = fract(x);\n\n    float a = hash(i);\n    float b = hash(i + vec2(1.0, 0.0));\n    float c = hash(i + vec2(0.0, 1.0));\n    float d = hash(i + vec2(1.0, 1.0));\n\n    vec2 u = f * f * (3.0 - 2.0 * f);\n    return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;\n}\n\n#define PIXEL_SIZE 5.0\n#define SCROLL_SPEED 1.0\n\nvoid main() {\n    float v = 0.0;\n    \n    float coord2 = floor(gl_FragCoord.x / PIXEL_SIZE / 5.0 + time * 5.0 * SCROLL_SPEED) * PIXEL_SIZE * 0.05 - 10.0;\n    float height = fbm(coord2) * resolution.y / 2.0;\n    v = clamp((height - floor(gl_FragCoord.y / PIXEL_SIZE) * PIXEL_SIZE + resolution.y / 2.0) / (resolution.y * 0.02), 0.0, 1.0);\n    \n    vec3 col = pow(v, 0.35) * 1.3 * normalize(vec3(0.5, gl_FragCoord.xy / resolution.xy)) + vec3(v * 0.25);\n    \n    if (col.r < 0.1 && col.g < 0.1 && col.b < 0.1) {\n        gl_FragColor = vec4(0.0);\n        return;\n    }\n    \n    vec2 coord = floor(gl_FragCoord.xy / PIXEL_SIZE) * PIXEL_SIZE * 0.025 + vec2(time * 3.0 * SCROLL_SPEED, resolution.y / 2.0);\n    float v2 = noise2D(coord);\n    \n    gl_FragColor = vec4(1, 0.984, 0, 1.0) + vec4(v2, v2, v2, 0.0) / 2.0;\n    //gl_FragColor = vec4(0.788, 0.784, 0.38, 1.0);\n    //gl_FragColor = vec4(pow(v, 0.35) * 1.3 * normalize(vec3(0.5, gl_FragCoord.xy / resolution.xy)) + vec3(v * 0.25), 1.0);\n}\n\n";export default gfx;

